:root {
  --bg-tag: #f2ead8;
  --bg-header: #3b2f1e;
  --bg-body: #fdf8ef;
  --bg-contour: #e8dfc8;
  --bg-badge: #7a5c38;
  --bg-footer: #4a3825;
  --color-title: #f5ecd4;
  --color-series: #c8a96e;
  --color-sub: #a8916a;
  --color-spec-label: #7a5c38;
  --color-spec-val: #2c1f0e;
  --color-elev-num: #f5ecd4;
  --color-elev-unit: #c8a96e;
  --color-craftsman-label: #a8916a;
  --color-craftsman-name: #f5ecd4;
  --color-date-label: #a8916a;
  --color-date-val: #f5ecd4;
  --chip-cast-bg: #5c8a4a;
  --chip-cast-color: #e8f5e0;
  --chip-painted-bg: #4a6e8a;
  --chip-painted-color: #dceef8;
  --chip-pending-bg: #8a6a2a;
  --chip-pending-color: #fdf3d8;
  --contour-color: #b5a27a;
  --border-accent: #c8a96e;
}

.workshop-tag {
  width: 460px;
  background: var(--bg-tag);
  border: 2px solid var(--bg-header);
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.tag-header {
  background: var(--bg-header);
  padding: 8px 14px 7px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  border-bottom: 3px solid var(--border-accent);
}

.tag-series {
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: var(--color-series);
  text-transform: uppercase;
}

.tag-title {
  font-size: 18px;
  font-weight: 800;
  line-height: 1.1;
  color: var(--color-title);
  margin: 0;
  letter-spacing: 0.03em;
}

.tag-sub {
  font-size: 10px;
  font-weight: 400;
  color: var(--color-sub);
  letter-spacing: 0.05em;
}

.tag-body {
  background: var(--bg-body);
  display: flex;
  flex-direction: row;
  flex: 1;
}

.model-meta {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px 10px 14px;
  flex: 1;
  border-right: 1px solid var(--border-accent);
}

.elevation-badge {
  background: var(--bg-badge);
  border-radius: 4px;
  padding: 5px 10px;
  margin: 0;
  display: flex;
  flex-direction: row;
  align-items: baseline;
  gap: 5px;
  border: 1px solid var(--border-accent);
  align-self: flex-start;
}

.elev-num {
  font-size: 18px;
  font-weight: 800;
  color: var(--color-elev-num);
  line-height: 1;
  letter-spacing: 0.04em;
}

.elev-unit {
  font-size: 10px;
  font-weight: 600;
  color: var(--color-elev-unit);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.model-specs {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.spec-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 6px;
  border-bottom: 1px dotted var(--contour-color);
  padding-bottom: 3px;
}

.spec-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--color-spec-label);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  white-space: nowrap;
}

.spec-val {
  font-size: 10px;
  font-weight: 500;
  color: var(--color-spec-val);
  text-align: right;
}

.contour-panel {
  width: 110px;
  background: var(--bg-contour);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 7px;
  padding: 12px 8px;
}

.contour-line {
  border-radius: 50%;
  border: 2px solid var(--contour-color);
  flex-shrink: 0;
}

.c1 { width: 88px; height: 24px; }
.c2 { width: 70px; height: 19px; }
.c3 { width: 52px; height: 14px; }
.c4 { width: 36px; height: 10px; }
.c5 { width: 20px; height: 7px; }

.tag-footer {
  background: var(--bg-footer);
  padding: 7px 14px;
  display: flex;
  flex-direction: row;
  justify-content: space-between;
  align-items: center;
  gap: 6px;
  border-top: 2px solid var(--border-accent);
}

.craftsman-info,
.commission-date {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.craftsman-label,
.date-label {
  font-size: 8px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--color-craftsman-label);
}

.craftsman-name,
.date-val {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-craftsman-name);
  letter-spacing: 0.03em;
}

.date-label { color: var(--color-date-label); }
.date-val { color: var(--color-date-val); }

.status-chips {
  display: flex;
  flex-direction: row;
  gap: 4px;
  align-items: center;
}

.chip {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 3px 6px;
  border-radius: 3px;
}

.chip-cast {
  background: var(--chip-cast-bg);
  color: var(--chip-cast-color);
}

.chip-painted {
  background: var(--chip-painted-bg);
  color: var(--chip-painted-color);
}

.chip-pending {
  background: var(--chip-pending-bg);
  color: var(--chip-pending-color);
}
